import xml.etree.ElementTree as ET
from .utils import info


class CommissioningBaseFile(object):
    ID = '3221225472'

    def __init__(self, mocs):
        self.root = ET.Element('raml')
        self.cmdata = ET.SubElement(self.root, 'cmData', {'id': self.ID, 'scope': 'all', 'type': 'plan'})
        self._append_mocs(mocs)

    def write(self, output):
        commissioning_file = ET.ElementTree(self.root)
        commissioning_file.write(output, xml_declaration=True, encoding='utf-8')

    @info('Adding')
    def create(self, moc):
        moc.set('operation', 'create')
        self.cmdata.append(moc)

    def _append_mocs(self, mocs):
        for moc in mocs:
            self.create(moc)
